import { Component, OnDestroy, OnInit, computed, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Category, Question } from './models/question';
import { QuestionsService } from './services/questions.service';

type UIcategory = { key: Category; label: string };

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnInit, OnDestroy {
  title = 'Simulado FGV – Câmara de Porto Velho';
  categories: UIcategory[] = [
    { key: 'PORTUGUES', label: 'Português' },
    { key: 'DIREITO_CONSTITUCIONAL', label: 'Direito Constitucional' },
    { key: 'MISTO', label: 'Misto' }
  ];

  category = signal<Category>('PORTUGUES');
  pool = signal<Question[]>([]);
  order = signal<string[]>([]);
  idx = signal<number>(0);

  answers = signal<Record<string, number>>({});
  showExplain = signal<Record<string, boolean>>({});
  started = signal<boolean>(false);

  seconds = signal<number>(0);
  private timer: any;

  loading = signal<boolean>(false);
  error = signal<string | null>(null);
  readonly Math = Math;
  private readonly alphabet = 'abcdefghijklmnopqrstuvwxyz';

  constructor(private qService: QuestionsService) {}

  ngOnInit(): void { this.loadCategory(this.category()); }
  ngOnDestroy(): void { if (this.timer) clearInterval(this.timer); }

  total = computed(() => this.pool().length);
  current = computed(() => this.pool().find(q => q.id === this.order()[this.idx()]));
  answeredCount = computed(() => Object.keys(this.answers()).length);
  correctCount = computed(() =>
    this.pool().filter(q => this.answers()[q.id] === q.correctIndex).length
  );
  progressPct = computed(() => this.total() ? Math.round((this.answeredCount() / this.total()) * 100) : 0);
  mistakes = computed(() =>
    this.pool().filter(q => this.answers()[q.id] !== q.correctIndex)
  );

  loadCategory(cat: Category) {
    this.loading.set(true);
    this.error.set(null);
    this.category.set(cat);
    this.pool.set([]);
    this.order.set([]);
    this.idx.set(0);
    this.answers.set({});
    this.showExplain.set({});
    this.started.set(false);
    this.seconds.set(0);
    if (this.timer) clearInterval(this.timer);

    this.qService.listAllByCategory(cat).subscribe({
      next: (items) => {
        this.pool.set(items);
        const ids = items.map(q => q.id);
        this.order.set(this.shuffle(ids));
        this.loading.set(false);
      },
      error: (err) => {
        console.error(err);
        this.error.set('Falha ao carregar questões. Verifique se a API está rodando em http://localhost:3000.');
        this.loading.set(false);
      }
    });
  }

  start() {
    if (this.started()) return;
    this.started.set(true);
    this.timer = setInterval(() => this.seconds.update(s => s + 1), 1000);
  }

  restart() {
    this.order.set(this.shuffle(this.pool().map(q => q.id)));
    this.idx.set(0);
    this.answers.set({});
    this.showExplain.set({});
    this.started.set(false);
    this.seconds.set(0);
    if (this.timer) clearInterval(this.timer);
  }

  selectAnswer(q: Question, i: number) {
    if (!this.started()) return;
    if (q.id in this.answers()) return;
    this.answers.update(a => ({ ...a, [q.id]: i }));
    this.showExplain.update(s => ({ ...s, [q.id]: true }));
  }

  prev() { if (this.idx() > 0) this.idx.update(v => v - 1); }
  next() { if (this.idx() < this.total() - 1) this.idx.update(v => v + 1); }

  exportCSV() {
    const rows = this.pool().map(q => ({
      id: q.id,
      categoria: q.category,
      acerto: this.answers()[q.id] === q.correctIndex ? 1 : 0,
      marcado: this.answers()[q.id] != null ? q.options[this.answers()[q.id]] : '',
      correta: q.options[q.correctIndex],
    }));
    const header = Object.keys(rows[0] || { id:'', categoria:'', acerto:'', marcado:'', correta:'' });
    const csv = [header.join(';'),
      ...rows.map(r => header.map(h => String((r as any)[h]).replace(/;/g, ',')).join(';'))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `resultado_${this.category()}.csv`;
    a.click();
    URL.revokeObjectURL(a.href);
  }

  humanCategory(cat: Category): string {
    const m: Record<Category, string> = {
      'PORTUGUES': 'Português',
      'DIREITO_CONSTITUCIONAL': 'Direito Constitucional',
      'MISTO': 'Misto',
    };
    return m[cat];
  }

  letter(idx: number): string {
    return this.alphabet.charAt(idx);
  }

  isAnswered(id: string): boolean {
    return this.answers()[id] != null;
  }

  private shuffle<T>(arr: T[]): T[] {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }
}
<div class="container">
  <div class="header">
    <h1 style="margin:0">{{ title }}</h1>
    <div class="toolbar">
      <label class="meta">Categoria:</label>
      <select class="select" [ngModel]="category()" (ngModelChange)="loadCategory($event)">
        <option *ngFor="let c of categories" [value]="c.key">{{ c.label }}</option>
      </select>

      <button class="btn primary" (click)="start()" [disabled]="started()">Iniciar</button>
      <button class="btn ghost" (click)="restart()">Reiniciar</button>
      <button class="btn ghost" (click)="exportCSV()">Exportar CSV</button>
    </div>
  </div>

  <div class="card" style="margin-top:12px">
    <div class="content">
      <div class="progress"><div [style.width.%]="progressPct()"></div></div>
      <div class="meta" style="margin-top:6px">
        Progresso: {{ answeredCount() }}/{{ total() }} •
        Acertos: {{ correctCount() }} •
        Tempo: {{ Math.floor(seconds()/60) }}m {{ seconds()%60 }}s
      </div>
    </div>
  </div>

  <div *ngIf="loading()" class="card" style="margin-top:12px">
    <div class="content"><div class="meta">Carregando questões…</div></div>
  </div>
  <div *ngIf="error()" class="card" style="margin-top:12px">
    <div class="content alert">{{ error() }}</div>
  </div>

  <div *ngIf="current() as curr" class="card" style="margin-top:12px">
    <div class="content">
      <div class="badge">{{ humanCategory(curr.category) }}</div>
      <div style="font-weight:700; margin:8px 0">{{ idx()+1 }}. {{ curr.stem }}</div>

      <ul class="ul">
        <li *ngFor="let opt of curr.options; let i = index" style="margin-bottom:8px">
          <button
            class="option"
            [ngClass]="{
              correct: showExplain()[curr.id] && curr.correctIndex === i,
              wrong: showExplain()[curr.id] && answers()[curr.id] === i && curr.correctIndex !== i
            }"
            [disabled]="!started() || isAnswered(curr.id)"
            (click)="selectAnswer(curr, i)">
            <span class="mono">{{ letter(i) }})</span> {{ opt }}
          </button>
        </li>
      </ul>

      <div *ngIf="showExplain()[curr.id]" class="explain">
        <b>Comentário:</b> {{ curr.explanation }}
      </div>

      <div class="grid" style="margin-top:10px">
        <button class="btn ghost" (click)="prev()" [disabled]="idx()===0">Anterior</button>
        <div class="meta" style="text-align:center">{{ idx()+1 }} / {{ total() }}</div>
        <button class="btn primary" (click)="next()" [disabled]="idx()===total()-1">Próxima</button>
      </div>
    </div>
  </div>

  <div *ngIf="!loading() && !error() && total()===0" class="card" style="margin-top:12px">
    <div class="content">
      <div class="meta">Nenhuma questão encontrada para esta categoria.</div>
    </div>
  </div>

  <div *ngIf="answeredCount()===total() && total()>0" class="card" style="margin-top:12px">
    <div class="content">
      <h2 style="margin-top:0">Relatório Final</h2>
      <div class="meta">Nota: {{ correctCount() }}/{{ total() }} ({{ (correctCount()/total())*100 | number:'1.0-0' }}%)</div>
      <div class="meta">Aprovado? {{ (correctCount()/total())*100 >= 70 ? 'Sim' : 'Não' }}</div>

      <div style="margin-top:8px">
        <h3 style="margin-bottom:6px">Erros comentados</h3>
        <ul style="padding-left:18px">
          <li *ngFor="let q of mistakes()" style="margin-bottom:6px">
            <b>{{ q.id }}</b> – {{ q.stem }}<br>
            <span class="meta">
              Marcada: {{ answers()[q.id] != null ? q.options[answers()[q.id]] : '(em branco)' }}
              • Correta: {{ q.options[q.correctIndex] }}
            </span><br>
            <span class="meta">Comentário: {{ q.explanation }}</span>
          </li>
        </ul>
      </div>
    </div>
  </div>

  <div class="footer">Frontend Angular Standalone • Consome API em <code>/api</code> (proxy para http://localhost:3000)</div>
</div>
